CREATE TABLE `users` (`id` INTEGER NOT NULL AUTO_INCREMENT, `full_name` VARCHAR(160) NOT NULL, `login` VARCHAR(160) NOT NULL, `password_hash` VARCHAR(255) NOT NULL, `profile` ENUM('ADMINISTRADOR','MEDICO','SECRETARIA') NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `users_login_key` (`login`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `clinics` (`id` INTEGER NOT NULL AUTO_INCREMENT, `legal_name` VARCHAR(180) NOT NULL, `trade_name` VARCHAR(180) NOT NULL, `cnpj` VARCHAR(18) NOT NULL, `cnae` VARCHAR(20) NOT NULL, `address` TEXT NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `doctors` (`id` INTEGER NOT NULL AUTO_INCREMENT, `full_name` VARCHAR(160) NOT NULL, `crm` VARCHAR(40) NOT NULL, `rqe` VARCHAR(40) NOT NULL, `specialty` VARCHAR(120) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `insurances` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(160) NOT NULL, `ans` VARCHAR(40) NOT NULL, `value` DECIMAL(10,2) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `procedures` (`id` INTEGER NOT NULL AUTO_INCREMENT, `name` VARCHAR(160) NOT NULL, `value` DECIMAL(10,2) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
